mapper.select:
SELECT
    pr_head.*
FROM
    scc_npm_pr_require_head sou_pr_head
left join scc_pr_requirement_head pr_head on sou_pr_head.REQUIREMENT_HEAD_ID = pr_head.REQUIREMENT_HEAD_ID
where
    1 = 1
    AND pr_head.AUDIT_STATUS in ('APPROVED','ABANDONED')

    AND pr_head.DEMAND_TYPE = #{demandType}


    AND (
        pr_head.CATEGORY_CODE LIKE concat('%', concat(#{categoryCode}, '%'))
        OR
        pr_head.CATEGORY_NAME LIKE concat('%', concat(#{categoryCode}, '%'))
    )


    AND sou_pr_head.PROJECT_NAME LIKE concat('%', concat(#{projectName}, '%'))


    AND sou_pr_head.PROJECT_ADDRESS LIKE concat('%', concat(#{projectAddress}, '%'))


    AND exists (
        SELECT sou_pr_group.REQUIREMENT_HEAD_ID FROM scc_npm_pr_require_group sou_pr_group
        WHERE sou_pr_group.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID
        AND sou_pr_group.GROUP_TYPE LIKE '%TECH%'
        AND sou_pr_group.USERNAME = #{techUsername}
    )


    AND exists (
        SELECT sou_pr_group.REQUIREMENT_HEAD_ID FROM scc_npm_pr_require_group sou_pr_group
        WHERE sou_pr_group.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID
        AND sou_pr_group.GROUP_TYPE LIKE '%SOU%'
        AND sou_pr_group.USERNAME = #{souUsername}
    )


    AND exists (
        SELECT sou_pr_group.REQUIREMENT_HEAD_ID FROM scc_npm_pr_require_group sou_pr_group
        WHERE sou_pr_group.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID
        AND sou_pr_group.GROUP_TYPE LIKE '%SOU%'
        AND sou_pr_group.DEPARTMENT_NAME LIKE concat('%', concat(#{souUserDeptName}, '%'))
    )


    AND pr_head.APPLY_DATE >= #{applyDateFrom}


    AND pr_head.APPLY_DATE <= #{applyDateTo}


    AND (
        pr_head.APPLY_BY LIKE concat('%', concat(#{applyBy}, '%'))
        OR
        pr_head.APPLY_BY_NICKNAME LIKE concat('%', concat(#{applyBy}, '%'))
    )


    AND (
        pr_head.CEEA_DEPARTMENT_ID LIKE concat('%', concat(#{departmentId}, '%'))
        OR
        pr_head.CEEA_DEPARTMENT_NAME LIKE concat('%', concat(#{departmentId}, '%'))
    )


    AND exists (
    SELECT sou_pr_group.REQUIREMENT_HEAD_ID FROM scc_npm_pr_require_group sou_pr_group
    WHERE sou_pr_group.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID
    AND sou_pr_group.GROUP_TYPE LIKE '%VENDOR%'
    AND sou_pr_group.USERNAME = #{vendorUsername}
    )


    AND exists (
    SELECT sou_pr_group.REQUIREMENT_HEAD_ID FROM scc_npm_pr_require_group sou_pr_group
    WHERE sou_pr_group.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID
    AND sou_pr_group.GROUP_TYPE LIKE '%VENDOR%'
    AND sou_pr_group.DEPARTMENT_NAME LIKE concat('%', concat(#{vendorUserDeptName}, '%'))
    )


    AND pr_head.REQUIREMENT_HEAD_NUM LIKE concat('%', concat(#{requirementHeadNum}, '%'))


    AND sou_pr_head.HAS_ASSIGNED = #{hasAssigned}


    AND sou_pr_head.REQUIRE_FROM = #{requireFrom}


    AND sou_pr_head.HAS_SEND_SOU_PROFILE = #{hasSendSouProfile}


    AND sou_pr_head.SEND_SOU_PROFILE_END_DATE >= #{sendSouProfileEndDateFrom}


    AND sou_pr_head.SEND_SOU_PROFILE_END_DATE <= #{sendSouProfileEndDateFrom}


    AND sou_pr_head.PROJECT_MONTH = #{projectMonth}


    AND (
        sou_pr_head.ORG_BU_CODE LIKE concat('%', concat(#{orgBuCode}, '%'))
        OR
        sou_pr_head.ORG_BU_NAME LIKE concat('%', concat(#{orgBuCode}, '%'))
    )


    AND (
        pr_head.ORG_CODE LIKE concat('%', concat(#{orgCode}, '%'))
        OR
        pr_head.ORG_NAME LIKE concat('%', concat(#{orgCode}, '%'))
    )


    AND sou_pr_head.PREFIX_TECH_DISCUSSION = #{prefixTechDiscussion}


    AND sou_pr_head.PUBLIC_END_TIME >= #{publicEndTimeFrom}


    AND sou_pr_head.PUBLIC_END_TIME <= #{publicEndTimeTo}


    AND sou_pr_head.SOU_REQ_STATUS = #{souReqStatus}


    AND sou_pr_head.HAS_CREATE_SOU_REQ = #{hasCreateSouReq}


    AND sou_pr_head.APPROVAL_PASS_TIME >= #{approvalPassTimeFrom}


    AND sou_pr_head.APPROVAL_PASS_TIME <= #{approvalPassTimeTo}


    AND sou_pr_head.NEED_PUBLIC = #{needPublic}


      and sou_pr_head.IF_APPOINT_BRAND = #{ifAppointBrand}


    and sou_pr_head.IF_QUALIFY_UNIT = #{ifQualifyUnit}


    and sou_pr_head.SPECIAL_SOU_TYPE = #{specialSouType}


    and sou_pr_head.NO_PUBLIC_REASON_CHOOSE = #{noPublicReasonChoose}



    and sou_pr_head.NO_PUBLIC_REASON like CONCAT('%',#{noPublicReason},'%')


    and EXISTS (select * from scc_npm_pr_require_vendor v where v.REQUIREMENT_HEAD_ID = sou_pr_head.REQUIREMENT_HEAD_ID and v.VENDOR_NAME like CONCAT('%',#{vendorName},'%'))




ORDER BY sou_pr_head.APPROVAL_PASS_TIME desc, pr_head.REQUIREMENT_HEAD_ID desc
